import logging

import streamlit as st

logger = logging.getLogger(__name__)

streamlit_handler = StreamlitLogHandler()
streamlit_handler.setLevel(logging.INFO)
logger.addHandler(streamlit_handler)
logger.setLevel(logging.DEBUG)

object_to_log = {"key": "value"}

if st.button("Make debug log"):
    logger.debug("Example debug log message")
if st.button("Make debug log with object shown"):
    logger.debug("Example debug log message", extra={"object": object_to_log})

if st.button("Make warning log"):
    logger.warning("Example warning log message")
if st.button("Make warning log with object shown"):
    logger.warning("Example warning log message", extra={"object": object_to_log})

if st.button("Make error log"):
    logger.error("Example error log message")
if st.button("Make error log with object shown"):
    logger.error("Example error log message", extra={"object": object_to_log})

if st.button("Make critical log"):
    logger.critical("Example critical log message")
if st.button("Make critical log with object shown"):
    logger.critical("Example critical log message", extra={"object": object_to_log})
if st.button("Raising an exception"):
    try:
        1 / 0
    except ZeroDivisionError as e:
        raise Exception("Example error log message with exception") from e    
if st.button("Make error log with exception (doesn't stop execution)"):
    try:
        1 / 0
    except ZeroDivisionError as e:
        logger.error("Example error log message with exception.", exc_info=e)
if st.button("Make error log with exception and then stop execution"):
    try:
        1 / 0
    except ZeroDivisionError as e:
        logger.error("Example error log message with exception.", exc_info=e)
        raise Exception("Example exception.") from e
if st.button("Make error log with exception and object shown (doesn't stop execution)"):
    try:
        1 / 0
    except ZeroDivisionError as e:
        logger.error("Example error log message with exception and object shown.", exc_info=e, extra={"object": object_to_log})
if st.button("Make error log with exception and object shown and then stop execution"):
    try:
        1 / 0
    except ZeroDivisionError as e:
        logger.error("Example error log message with exception and object shown.", exc_info=e, extra={"object": object_to_log})
        raise Exception("Example exception.") from e
